    async def create(
        self,
        *,
        event_type: str,
        start: str,
        attendee: SchedulingAttendeeInput,
        idempotency_key: typing.Optional[str] = None,
        host: typing.Optional[str] = OMIT,
        attributes: typing.Optional[typing.Dict[str, CreateBookingRequestAttributesValue]] = OMIT,
        duration_minutes: typing.Optional[int] = OMIT,
        guests: typing.Optional[typing.Sequence[SchedulingGuestInput]] = OMIT,
        answers: typing.Optional[typing.Dict[str, CreateBookingRequestAnswersValue]] = OMIT,
        location: typing.Optional[CreateBookingRequestLocation] = OMIT,
        metadata: typing.Optional[typing.Dict[str, str]] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> SchedulingBooking:
        """
        Books a slot, or joins a group session. Without a `host`, a pool chooses fairly among those free. An event type that requires approval answers with a `pending_approval` booking.

        Parameters
        ----------
        event_type : str
            The event type's id or uid.

        start : str
            An ISO 8601 instant with an offset.

        attendee : SchedulingAttendeeInput

        idempotency_key : typing.Optional[str]
            Makes retries safe: a repeated request with the same key and body returns the original booking instead of creating another, for 24 hours. A refused request keeps no key. 1-256 characters.

        host : typing.Optional[str]
            A specific host (id or uid). Default: chosen fairly from those free.

        attributes : typing.Optional[typing.Dict[str, CreateBookingRequestAttributesValue]]
            Only choose among pool hosts matching all of these.

        duration_minutes : typing.Optional[int]
            One of the event type's `duration_options`.

        guests : typing.Optional[typing.Sequence[SchedulingGuestInput]]
            Up to the event type's `max_guests`.

        answers : typing.Optional[typing.Dict[str, CreateBookingRequestAnswersValue]]
            Answers to the event type's questions. Stored encrypted, and returned only by retrieving the booking.

        location : typing.Optional[CreateBookingRequestLocation]
            One of the event type's `locations`, with your link filled in if it has none.

        metadata : typing.Optional[typing.Dict[str, str]]
            Your own key-value pairs. Don't put sensitive data here.

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        SchedulingBooking
            The booking.

        Examples
        --------
        import asyncio

        from coss import AsyncCoss, SchedulingAttendeeInput

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.scheduling.bookings.create(
                idempotency_key="welcome-user-123",
                event_type="evtype_01kd2m9a0b1c2d3e4f5g6h7j8m",
                start="2027-01-04T15:00:00.000Z",
                attendee=SchedulingAttendeeInput(
                    uid="patient_77",
                    name="Sam Lee",
                    email="sam@example.com",
                    time_zone="UTC",
                ),
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.create(
            event_type=event_type,
            start=start,
            attendee=attendee,
            idempotency_key=idempotency_key,
            host=host,
            attributes=attributes,
            duration_minutes=duration_minutes,
            guests=guests,
            answers=answers,
            location=location,
            metadata=metadata,
            request_options=request_options,
        )
        return _response.data

